import unittest

import auth


class AuthTests(unittest.TestCase):
    def test_admin_borra(self):
        auth.USERS["tmp"] = {"role": "user"}
        self.assertTrue(auth.delete_user("ana", "tmp"))
        self.assertNotIn("tmp", auth.USERS)


if __name__ == "__main__":
    unittest.main()
